import numpy as np

def forward_difference(f, x, h=1e-5):
    return (f(x + h) - f(x)) / h

def central_difference(f, x, h=1e-5):
    return (f(x + h) - f(x - h)) / (2 * h)

def five_point_stencil(f, x, h=1e-5):
    return (-f(x + 2*h) + 8*f(x + h) - 8*f(x - h) + f(x - 2*h)) / (12 * h)

def richardson_extrapolation(f, x, h=0.1, order=4):
    D = np.zeros((order, order))
    for i in range(order):
        h_i = h / (2**i)
        D[i, 0] = central_difference(f, x, h_i)
    for j in range(1, order):
        for i in range(j, order):
            D[i, j] = (4**j * D[i, j-1] - D[i-1, j-1]) / (4**j - 1)
    return D[order-1, order-1]

def numerical_gradient(f, x, h=1e-5):
    n = len(x)
    grad = np.zeros(n)
    for i in range(n):
        x_plus = x.copy()
        x_plus[i] += h
        x_minus = x.copy()
        x_minus[i] -= h
        grad[i] = (f(x_plus) - f(x_minus)) / (2 * h)
    return grad

x = np.pi / 4
exact = np.cos(x)
print(f"Forward: {forward_difference(np.sin, x):.10f}, error: {abs(forward_difference(np.sin, x) - exact):.2e}")
print(f"Central: {central_difference(np.sin, x):.10f}, error: {abs(central_difference(np.sin, x) - exact):.2e}")
print(f"Five-point: {five_point_stencil(np.sin, x):.10f}, error: {abs(five_point_stencil(np.sin, x) - exact):.2e}")
